//! GENERATED golden tests: every case verified against the oracle at generation time.

use barcode_microqr::{encode_bytes, Level, Mode, Version};

fn check(path: &str, contents: &str, version: Version, level: Level, mode: Mode, len: usize) {
    let size = match version { Version::M1 => 11, Version::M2 => 13, Version::M3 => 15, Version::M4 => 17 };
    let payload = |s: &str| if mode == Mode::Byte {
        (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i+2], 16).unwrap()).collect::<Vec<u8>>()
    } else { s.replace('_', " ").into_bytes() };
    let mut n = 0;
    for line in contents.lines().skip(1) {
        let mut it = line.split_whitespace();
        let p = payload(it.next().unwrap());
        let class: usize = it.next().unwrap().parse().unwrap();
        let hex = it.next().unwrap();
        assert_eq!(p.len(), len);
        let sym = encode_bytes(&p, version, level, Some(mode), Some(class))
            .unwrap_or_else(|| panic!("{}: encode failed", path));
        assert_eq!(sym.size, size);
        let mut bits = Vec::new();
        for c in hex.chars() {
            let v = c.to_digit(16).unwrap() as u8;
            for i in (0..4).rev() { bits.push((v >> i) & 1); }
        }
        for i in 0..size * size {
            assert_eq!(sym.cells[i], bits[i], "{}: cell ({},{})"
                , path, i % size, i / size);
        }
        n += 1;
    }
    assert!(n > 0);
}

